package com.aoo.bcg.wordcard;import com.aoo.bcg.gamespi.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class YcsdrNineStageAcceptanceTest{
 @Test void createJoinReadyStartRotateReconnectRestoreReplay(){YcsdrGameProvider p=new YcsdrGameProvider();YcsdrSession s=(YcsdrSession)p.roomFactory().create(new RoomCreationContext(40401,10,Map.of())).requireAuthoritativeSession();StatePayload empty=StatePayload.copyOf(s.authoritativeState());s.execute(c(1,1,20,"join",Map.of()));s.execute(c(2,1,20,"ready",Map.of()));Map<String,Object>v=s.execute(c(3,0,10,"start",Map.of())).body().asMap();assertEquals("PLAYING",v.get("phase"));@SuppressWarnings("unchecked")Map<Integer,Object>seats=(Map<Integer,Object>)v.get("seats");@SuppressWarnings("unchecked")Map<String,Object>mine=(Map<String,Object>)seats.get(0);int card=(Integer)((List<?>)mine.get("cards")).getFirst();s.execute(c(4,0,10,"operation",Map.of("operation","OUT","card",card)));assertEquals(1,s.viewFor(20).get("currentSeat"));StatePayload replay=p.eventReplayProvider().orElseThrow().replay(empty,s.events());assertEquals(s.authoritativeState(),replay.asMap());assertEquals(s.viewFor(20),p.restoreAuthoritativeSession(replay).orElseThrow().viewFor(20));}
 @Test void legalSelfDrawUsesYcsdrScoring(){YcsdrGameProvider p=new YcsdrGameProvider();Map<String,Object>x=base();YcsdrSession s=(YcsdrSession)p.restoreAuthoritativeSession(x).orElseThrow();s.execute(new GameCommandRequest("wordcard.ycsdr.dispatch","hu",1,40402,0,"1.0.0","10",0,Map.of("action","operation","payload",Map.of("operation","HU","pattern","TAI_HU","huShu",2,"mao",1,"kan",1))));assertEquals(9L,s.settlement(1,"1.0.0").scoreDelta().get(10L));assertEquals(-9L,s.settlement(1,"1.0.0").scoreDelta().get(20L));}
 private static Map<String,Object>base(){Map<String,Object>x=new LinkedHashMap<>();x.put("schemaVersion",1);x.put("roomId",40402L);x.put("ownerId",10L);x.put("rules",Map.of());x.put("players",Map.of(0,10L,1,20L));x.put("ready",List.of(1));x.put("hands",Map.of(0,List.of(1101,2101,1201,1202,1203,1301,1302,1303),1,List.of(1401)));x.put("melds",Map.of(0,List.of(),1,List.of()));x.put("scores",Map.of(0,0L,1,0L));x.put("deck",List.of(1402));x.put("discards",List.of());x.put("sequence",0L);x.put("stateVersion",0L);x.put("current",0);x.put("lastOut",-1);x.put("lastOutSeat",-1);x.put("winner",-1);x.put("loser",-1);x.put("started",true);x.put("finished",false);return x;}
 private static GameCommandRequest c(long n,int seat,long p,String a,Map<String,Object>x){return new GameCommandRequest("wordcard.ycsdr.dispatch","y-"+n,n,40401,0,"1.0.0",String.valueOf(p),seat,Map.of("action",a,"payload",x));}}
